import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.XXezeKOl.js";const b=JSON.parse('{"title":"ReAct","description":"精读 ReAct：让模型交替进行推理（Thought）和行动（Action），这是今天大多数 Agent 循环的原型。","frontmatter":{"title":"ReAct","description":"精读 ReAct：让模型交替进行推理（Thought）和行动（Action），这是今天大多数 Agent 循环的原型。"},"headers":[],"relativePath":"papers/react.md","filePath":"papers/react.md","lastUpdated":null}'),i={name:"papers/react.md"};function t(p,a,r,o,c,h){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="react" tabindex="-1">ReAct <a class="header-anchor" href="#react" aria-label="Permalink to &quot;ReAct&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：ReAct: Synergizing Reasoning and Acting in Language Models</li><li>作者：Shunyu Yao、Jeffrey Zhao、Dian Yu、Nan Du、Izhak Shafran、Karthik Narasimhan、Yuan Cao（Princeton University、Google）</li><li>年份：2022（ICLR 2023）</li><li>链接：<a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">arXiv:2210.03629</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>让模型以&quot;Thought → Action → Observation&quot;的形式交替推理和调用外部工具，推理帮助制定和调整计划，行动带回真实信息修正推理，二者结合比单独推理或单独行动都更可靠。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>在 ReAct 之前，两条研究路线是分开的：</p><ul><li><strong>只推理</strong>（如 <a href="/papers/chain-of-thought">Chain-of-Thought</a>）：模型完全依赖自己的内部知识，遇到不知道或记错的事实时会一本正经地编造，而且错误会沿着推理链传播。</li><li><strong>只行动</strong>：模型直接输出一连串动作与环境交互，但没有显式的思考过程，难以分解目标、跟踪进度，也难以在出错后调整。</li></ul><p>作者的问题是：能不能把两者结合起来，让推理指导行动，让行动的结果反过来校正推理？</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>ReAct 把模型的每一步输出分成两类：Thought（自由文本的思考）和 Action（对外部环境的调用），环境返回 Observation 后再进入下一轮。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  问题: &quot;某部电影的导演出生在哪个城市？&quot;</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>  ┌───────────────────────────────────────────────────┐</span></span>
<span class="line"><span>  │ Thought 1: 我需要先查这部电影的导演是谁              │ ◀─┐</span></span>
<span class="line"><span>  │ Action 1:  search[电影名]                          │   │</span></span>
<span class="line"><span>  └───────────────────────────────────────────────────┘   │</span></span>
<span class="line"><span>          │                                              │</span></span>
<span class="line"><span>          ▼                                              │</span></span>
<span class="line"><span>  ┌───────────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>  │ Observation 1: (工具返回) 该片由 X 执导……           │   │  循环直到</span></span>
<span class="line"><span>  └───────────────────────────────────────────────────┘   │  Action = finish</span></span>
<span class="line"><span>          │                                              │</span></span>
<span class="line"><span>          ▼                                              │</span></span>
<span class="line"><span>  ┌───────────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>  │ Thought 2: 导演是 X，接下来查 X 的出生地             │ ──┘</span></span>
<span class="line"><span>  │ Action 2:  search[X]                               │</span></span>
<span class="line"><span>  └───────────────────────────────────────────────────┘</span></span>
<span class="line"><span>          │  ……</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>  Action N: finish[答案]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>实现上非常朴素：用几个人工写好的完整轨迹作为 Few-shot 示例，让模型按同样的格式续写；程序解析出 Action，执行后把 Observation 拼回提示词，再让模型继续生成。</p><p>论文在知识类任务上只给模型提供了一个非常简单的 Wikipedia 接口（搜索、在页面中查找、给出答案），在交互类任务上使用文本游戏环境和模拟购物网站的动作空间。</p><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><p>论文在四类任务上做了评估：多跳问答（HotpotQA）、事实核查（FEVER）、文本家居环境中的交互任务（ALFWorld）和网购任务（WebShop）。</p><ul><li><strong>知识类任务：</strong> ReAct 通过查询外部信息明显减少了事实幻觉，推理过程也更可信、更容易解释。但单独使用时并不总是优于思维链，因为搜索结果不理想时会被带偏。论文发现把 ReAct 和思维链（配合自洽投票）结合，在两种方法之间按条件切换，效果最好。</li><li><strong>交互类任务：</strong> 在 ALFWorld 和 WebShop 上，仅用一两个示例的 ReAct 就超过了使用大量数据训练的模仿学习和强化学习方法。显式的 Thought 帮助模型分解目标、记住进度。</li><li><strong>错误分析：</strong> 常见的失败包括反复执行相同动作陷入循环、搜索返回无用信息后无法恢复。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>ReAct 就是 Agent 循环的骨架。</strong> 今天的 Tool Calling 本质上把&quot;解析 Action 文本&quot;变成了结构化的工具调用，但&quot;思考 → 调用 → 观察 → 再思考&quot;的循环没有变。</li><li><strong>Observation 的质量决定上限。</strong> 论文中很多失败来自工具返回的信息不好，这说明工具设计（返回什么、返回多少、如何报错）和提示词一样重要。</li><li><strong>必须防循环。</strong> 重复动作是 ReAct 最典型的失败模式，工程上要有最大步数、重复检测和预算限制。</li><li><strong>推理轨迹是可观测性的基础。</strong> 把每一步 Thought 和 Action 记录下来，出问题时才能定位。</li><li><strong>混合策略往往比单一策略好。</strong> 能直接回答的就直接回答，需要外部信息时再行动。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>依赖 Few-shot 示例和固定格式，当时的模型输出格式不稳定时需要额外处理。今天的原生 Tool Calling 已经缓解了这个问题。</li><li>每一步都要调用一次模型，步骤多时延迟和成本线性增长。</li><li>一步一步贪心地决策，缺乏全局规划，长任务容易偏离目标。这也是后来 Plan-and-Execute、<a href="/papers/reflexion">Reflexion</a> 等方法要解决的问题。</li><li>论文中的工具非常简单，真实环境中工具更多、返回更复杂，难度会显著上升。</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></li><li><a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a></li><li><a href="/guide/05-tool-calling/concept">工具调用原理</a></li><li><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li><li><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></li><li>实战项目：<a href="/projects/03-react-agent">03 手写 ReAct Agent</a></li></ul>`,23)])])}const g=n(i,[["render",t]]);export{b as __pageData,g as default};
